#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char buffer[20];
    int count;
    int data_value = 42;
    const char *label = "Result";

    // Use snprintf for safe, bounded formatting into a string buffer
    // The required output size (28) exceeds the buffer size (20).
    count = snprintf(buffer, sizeof(buffer), 
                     "%s Status: OK, Value: %d (%.1f)", 
                     label, data_value, 42.5);

    if (count < 0) {
        fprintf(stderr, "Error during snprintf processing.\n");
        return 1;
    }

    // Check if the output was truncated (count is the required size)
    if ((size_t)count >= sizeof(buffer)) {
        printf("Output was truncated. Required size: %d bytes.\n", count + 1);
    }

    // Output the formatted string (which is null-terminated up to 19 chars)
    printf("Buffer contents: [%s]\n", buffer);

    // Standard printf writing directly to stdout
    count = printf("\n--- Final Summary: Code %d ---\n", 200);
    if (count < 0) {
        perror("printf failed");
    }

    return 0;
}
